mapper.select:
SELECT cm.id AS id, CONCAT('Graduation Audit Self-check Form-', COALESCE(COALESCE(su.name_en, su.name_ch), '')) AS graduationForm, su.login_name AS studentId, su.name_en AS nameEn, su.name_ch AS nameCh, su.contact_tel AS contactTel, su.email AS email, cm.grade AS grade, cm.major AS major, cm.status, CASE WHEN cm.status IN(0) THEN 'Unfilled' WHEN cm.status = 1 THEN 'Submitted' WHEN cm.status = 2 THEN 'Rejected' WHEN cm.status = 3 THEN 'Acknowledged' WHEN cm.status = 4 THEN 'Invalid' ELSE '' END AS statusText, TO_CHAR(cm.student_submit_time,'YYYY-MM-DD') AS submitTime, cm.student_check_box AS studentCheckBox FROM biz_course_master cm JOIN sys_user su ON su.id = cm.student_id WHERE cm.remove_flag = 0 AND su.remove_flag = 0
AND cm.status = #{condition.status}
AND cm.student_submit_time >= #{condition.startTime}
AND cm.student_submit_time <= #{condition.endTime}
AND cm.officer_checked_date >= #{condition.startTime}
AND cm.officer_checked_date <= #{condition.endTime}
AND su.expected_year = #{condition.expectedGraduationTerm}
AND cm.major = #{condition.major}
AND cm.grade LIKE CONCAT('%', #{condition.grade}, '%')
AND cm.student_check_box = #{condition.studentCheckBox}
AND su.login_name LIKE CONCAT('%', #{condition.keyword}, '%')
AND ( su.name_en LIKE CONCAT('%', #{condition.keyword}, '%') OR su.name_ch LIKE CONCAT('%', #{condition.keyword}, '%') )
order by cm.updated_date desc
